begin;
set local lock_timeout = '30s';

-- GENERATED by scripts/gen-migrations.mjs from supabase/templates. Do not edit by hand.
-- Gate 11: standard meeting types and Microsoft (Outlook) calendar, D-044. Additive; replaces functions in place.
-- Meeting types are a fixed catalog (INITIAL 30 min, DIAGNOSTIC 1 h, MONTHLY 30 min, PLANNING 1 h) used by booking links,
-- by meetings the consultant creates directly, and by the CRM relationship history. OTHER is allowed for direct meetings.

-- ---------------------------------------------------------------- Microsoft as a second calendar provider
alter table cw_prod.calendar_connections drop constraint calendar_connections_provider_check;
alter table cw_prod.calendar_connections add constraint calendar_connections_provider_check check (provider in ('GOOGLE', 'MICROSOFT'));
alter table cw_prod.crm_events drop constraint crm_events_sync_provider_check;
alter table cw_prod.crm_events add constraint crm_events_sync_provider_check check (sync_provider in ('GOOGLE', 'MICROSOFT'));

create or replace function cw_prod.calendar_connection_save(p_provider text, p_email text, p_refresh_token text, p_scopes text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_conn cw_prod.calendar_connections; v_secret uuid;
begin
  if not cw_prod_private.is_staff() then perform cw_prod_private.deny(); end if;
  if p_provider not in ('GOOGLE', 'MICROSOFT') or coalesce(length(p_refresh_token), 0) < 10 then raise exception 'invalid connection' using errcode = '22023'; end if;
  select * into v_conn from cw_prod.calendar_connections where user_id = auth.uid() and provider = p_provider for update;
  if v_conn.vault_secret_id is not null then
    perform vault.update_secret(v_conn.vault_secret_id, p_refresh_token);
    v_secret := v_conn.vault_secret_id;
  else
    v_secret := vault.create_secret(p_refresh_token, 'cw_prod.calendar.' || p_provider || '.' || auth.uid()::text || '.' || gen_random_uuid()::text,
                                    'Campos Wealth calendar refresh token');
  end if;
  insert into cw_prod.calendar_connections (user_id, provider, account_email, scopes, status, vault_secret_id, connected_at, last_checked_at, last_error)
  values (auth.uid(), p_provider, nullif(lower(btrim(p_email)), ''), left(coalesce(p_scopes, ''), 500), 'CONNECTED', v_secret, now(), now(), null)
  on conflict (user_id, provider) do update
    set account_email = excluded.account_email, scopes = excluded.scopes, status = 'CONNECTED', vault_secret_id = v_secret,
        connected_at = now(), last_checked_at = now(), last_error = null
  returning id into v_conn.id;
  perform cw_prod_private.write_audit('PERMISSION_CHANGE', 'calendar_connections', v_conn.id::text, null, null,
    jsonb_build_object('provider', p_provider, 'status', 'CONNECTED'));
  return v_conn.id;
end $$;

-- Microsoft rotates refresh tokens: store the newest one for the caller's own connection.
create function cw_prod.calendar_connection_rotate(p_provider text, p_refresh_token text) returns void
language plpgsql security definer set search_path = '' as $$
declare v_secret uuid;
begin
  if not cw_prod_private.is_staff() or coalesce(length(p_refresh_token), 0) < 10 then perform cw_prod_private.deny(); end if;
  select vault_secret_id into v_secret from cw_prod.calendar_connections
   where user_id = auth.uid() and provider = p_provider and status = 'CONNECTED';
  if v_secret is not null then perform vault.update_secret(v_secret, p_refresh_token); end if;
end $$;

-- ---------------------------------------------------------------- standard meeting types
alter table cw_prod.booking_types add column meeting_kind text check (meeting_kind in ('INITIAL', 'DIAGNOSTIC', 'MONTHLY', 'PLANNING'));
create unique index booking_types_user_kind on cw_prod.booking_types (user_id, meeting_kind) where meeting_kind is not null;
alter table cw_prod.crm_events add column meeting_kind text check (meeting_kind in ('INITIAL', 'DIAGNOSTIC', 'MONTHLY', 'PLANNING', 'OTHER'));

create function cw_prod_private.meeting_kind_name(p_kind text) returns text
language sql immutable set search_path = '' as $$
  select case p_kind when 'INITIAL' then 'Reunião Inicial' when 'DIAGNOSTIC' then 'Reunião de Diagnóstico'
                     when 'MONTHLY' then 'Reunião Mensal' when 'PLANNING' then 'Reunião de Planejamento' end
$$;

-- One row per standard type and consultant (name comes from the catalog).
create function cw_prod.booking_kind_save(p_kind text, p_duration integer, p_description text, p_location_kind text,
                                        p_location_detail text, p_active boolean) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid;
begin
  if not cw_prod_private.is_staff() or cw_prod_private.meeting_kind_name(p_kind) is null then perform cw_prod_private.deny(); end if;
  insert into cw_prod.booking_types as t (user_id, meeting_kind, name, duration_minutes, description, location_kind, location_detail, active)
  values (auth.uid(), p_kind, cw_prod_private.meeting_kind_name(p_kind), p_duration, nullif(btrim(p_description), ''), p_location_kind,
          nullif(btrim(p_location_detail), ''), coalesce(p_active, true))
  on conflict (user_id, meeting_kind) where meeting_kind is not null do update
    set name = excluded.name, duration_minutes = excluded.duration_minutes, description = excluded.description,
        location_kind = excluded.location_kind, location_detail = excluded.location_detail, active = excluded.active
  returning id into v_id;
  return v_id;
end $$;

-- Type of a CRM meeting (relationship history). Owner only.
create function cw_prod.crm_event_set_kind(p_id uuid, p_kind text) returns void
language plpgsql security definer set search_path = '' as $$
declare e cw_prod.crm_events;
begin
  select * into e from cw_prod.crm_events where id = p_id for update;
  if not found or e.owner_id is distinct from auth.uid() then perform cw_prod_private.deny(); end if;
  perform cw_prod_private.require_contact(e.contact_id);
  update cw_prod.crm_events set meeting_kind = p_kind, updated_at = now() where id = p_id;
end $$;

-- Public page: types now carry their standard kind (used by per-type links: /agendar/<slug>?tipo=<kind>).
create or replace function cw_prod.booking_public_page(p_slug text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'owner_name', p.full_name, 'headline', b.headline, 'notice', b.min_notice_minutes, 'horizon', b.horizon_days, 'buffer', b.buffer_minutes,
    'types', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'duration', t.duration_minutes, 'description', t.description,
                                                           'location_kind', t.location_kind, 'kind', t.meeting_kind) order by t.duration_minutes, t.name)
                         from cw_prod.booking_types t where t.user_id = b.user_id and t.active), '[]'::jsonb),
    'windows', coalesce((select jsonb_agg(jsonb_build_object('weekday', w.weekday, 'start', w.start_min, 'end', w.end_min) order by w.weekday, w.start_min)
                           from cw_prod.booking_windows w where w.user_id = b.user_id), '[]'::jsonb))
    from cw_prod.booking_profiles b join cw_prod.profiles p on p.id = b.user_id and p.status = 'ACTIVE'
   where b.slug = lower(p_slug) and b.active
$$;

-- Refresh tokens of every connected calendar of the link owner (busy times on the public page).
create function cw_prod.booking_owner_tokens(p_slug text) returns table (provider text, token text)
language sql stable security definer set search_path = '' as $$
  select c.provider, s.decrypted_secret
    from cw_prod.calendar_connections c
    join cw_prod.booking_profiles b on b.user_id = c.user_id
    join vault.decrypted_secrets s on s.id = c.vault_secret_id
   where b.slug = lower(p_slug) and b.active and c.status = 'CONNECTED'
$$;

revoke all on function cw_prod.calendar_connection_rotate(text, text), cw_prod.booking_kind_save(text, integer, text, text, text, boolean),
  cw_prod.crm_event_set_kind(uuid, text), cw_prod.booking_owner_tokens(text), cw_prod_private.meeting_kind_name(text) from public, anon, authenticated;
grant execute on function cw_prod.calendar_connection_rotate(text, text), cw_prod.booking_kind_save(text, integer, text, text, text, boolean),
  cw_prod.crm_event_set_kind(uuid, text) to authenticated;
grant execute on function cw_prod.booking_owner_tokens(text) to service_role;

commit;

select 'migração 20 ok' as resultado, count(*) as funcoes_novas from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='cw_prod' and p.proname in ('booking_kind_save','crm_event_set_kind','calendar_connection_rotate','booking_owner_tokens');
